class ScheduleManager(QMainWindow):
    def __init__(self):
        super().__init__()
        self.schedule_file = "schedule.json"
        self.sound_file = "xxx.wav"
        self.schedule = []
        self.notification_timers = []
        self.current_gmt_offset = 3
        self.notification_threads = []
        
        self.countdown_timer = QTimer()
        self.countdown_timer.timeout.connect(self.update_countdowns)
        self.countdown_timer.start(1000)  # Update every second
        
        self.update_timer = QTimer()
        self.update_timer.timeout.connect(self.sort_and_update_list)
        self.update_timer.start(30000) 
        self.init_ui()
        self.setup_tray_icon()
    
        self.load_schedule()
        self.setup_notification_timers()

    def setup_tray_icon(self):
        if not QSystemTrayIcon.isSystemTrayAvailable():
            self.tray_icon = None
            return

        self.tray_icon = QSystemTrayIcon(self)
        icon = self.windowIcon()
        if icon.isNull() and NOTIFICATION_ICON_PATH and os.path.exists(NOTIFICATION_ICON_PATH):
            icon = QIcon(NOTIFICATION_ICON_PATH)
        self.tray_icon.setIcon(icon)
        self.tray_icon.setToolTip("Silkroad Schedule Manager")

        tray_menu = QMenu()
        restore_action = QAction("Show", self)
        restore_action.triggered.connect(self.restore_from_tray)
        tray_menu.addAction(restore_action)

        tray_menu.addSeparator()

        quit_action = QAction("Exit", self)
        quit_action.triggered.connect(self.quit_application)
        tray_menu.addAction(quit_action)

        self.tray_icon.setContextMenu(tray_menu)
        self.tray_icon.activated.connect(self.on_tray_icon_activated)
        self.tray_icon.show()

    def on_tray_icon_activated(self, reason):
        if reason in (QSystemTrayIcon.ActivationReason.Trigger,
                      QSystemTrayIcon.ActivationReason.DoubleClick):
            self.restore_from_tray()

    def restore_from_tray(self):
        self.showNormal()
        self.activateWindow()
        self.raise_()

    def quit_application(self):
        if self.tray_icon:
            self.tray_icon.hide()
        QApplication.quit()

    def changeEvent(self, event):
        if event.type() == QEvent.Type.WindowStateChange and self.isMinimized():
            if self.tray_icon and self.tray_icon.isVisible():
                event.ignore()
                QTimer.singleShot(0, self.hide)
                return
        super().changeEvent(event)

    def closeEvent(self, event):
        for thread in self.notification_threads:
            if thread.isRunning():
                thread.quit()
                thread.wait()
        self.update_timer.stop()
        self.countdown_timer.stop()
        if self.tray_icon:
            self.tray_icon.hide()
        super().closeEvent(event)
        
